	var n, x, pos int
	fmt.Scan(&n, &x, &pos)

	// Precompute factorials
	fact := make([]int64, n+1)
	fact[0] = 1
	for i := 1; i <= n; i++ {
		fact[i] = fact[i-1] * int64(i) % MOD
	}

	// Simulate binary search to find the path
	// We need to track which positions are "checked" and what constraints they impose
	// The binary search algorithm:
	// l = 0, r = n-1
	// while l <= r:
	//   m = (l + r) / 2
	//   if a[m] == x: return true
	//   else if a[m] < x: l = m + 1
	//   else: r = m - 1
	// return false

	// We want permutations where x is at position `pos` and the algorithm finds x.
	// This means that during the binary search, when we reach position `pos`, we find x.
	// Before reaching `pos`, the comparisons must direct the search towards `pos`.

	// Let's simulate the binary search path assuming x is at `pos`.
	// At each step, we have a range [l, r] and mid = (l+r)/2.
	// If mid == pos, we found x.
	// If mid < pos, we need a[mid] < x so that l becomes mid+1.
	// If mid > pos, we need a[mid] > x so that r becomes mid-1.

	// We need to count the number of permutations of {1, ..., n} such that:
	// 1. a[pos] = x
	// 2. For each mid encountered before pos (where mid != pos), if mid < pos then a[mid] < x, if mid > pos then a[mid] > x.

	// Let's collect all the mid positions that are checked before we hit pos.
	// Actually, we simulate the binary search and record which positions are "constrained".

	// Simulate binary search
	l := 0
	r := n - 1
	constrained := make(map[int]bool)
	found := false
	for l <= r {
		m := (l + r) / 2
		if m == pos {
			found = true
			break
		}
		// m is a position that gets checked
		constrained[m] = true
		if m < pos {
			// We need a[m] < x, so search goes right
			l = m + 1
		} else {
			// We need a[m] > x, so search goes left
			r = m - 1
		}
	}

	if !found {
		// This shouldn't happen if pos is valid, but just in case
		fmt.Println(0)
		return
	}

	// Now, the constrained positions (excluding pos) must have values:
	// - If mid < pos: a[mid] < x
	// - If mid > pos: a[mid] > x

	// Let's count how many constrained positions are less than pos and greater than pos.
	lessCount := 0
	greaterCount := 0
	for m := range constrained {
		if m < pos {
			lessCount++
		} else if m > pos {
			greaterCount++
		}
	}

	// The values available for positions less than pos (constrained) must be from {1, ..., x-1}
	// The values available for positions greater than pos (constrained) must be from {x+1, ..., n}

	// Number of ways to assign values to the constrained positions:
	// For lessCount positions, choose lessCount values from (x-1) available and permute them: P(x-1, lessCount)
	// For greaterCount positions, choose greaterCount values from (n-x) available and permute them: P(n-x, greaterCount)

	// If lessCount > x-1 or greaterCount > n-x, then it's impossible.
	if lessCount > x-1 || greaterCount > n-x {
		fmt.Println(0)
		return
	}

	// P(a, b) = a! / (a-b)!
	// ways_less = P(x-1, lessCount) = fact[x-1] / fact[x-1-lessCount]
	// ways_greater = P(n-x, greaterCount) = fact[n-x] / fact[n-x-greaterCount]

	// We need modular inverse for division
	// Since MOD is prime, we can use Fermat's little theorem

	// Let's compute P(a, b) = fact[a] * inv(fact[a-b]) % MOD
	invFact := make([]int64, n+1)
	// Compute inverse of fact[n]
	invFact[n] = modPow(fact[n], MOD-2, MOD)
	for i := n - 1; i >= 0; i-- {
		invFact[i] = invFact[i+1] * int64(i+1) % MOD
	}

	// P(a, b) = fact[a] * invFact[a-b] % MOD
	waysLess := fact[x-1] * invFact[x-1-lessCount] % MOD
	waysGreater := fact[n-x] * invFact[n-x-greaterCount] % MOD

	// The remaining positions (n - 1 - lessCount - greaterCount) can be filled with the remaining values in any order.
	// Total remaining values: n - 1 - lessCount - greaterCount
	// These are the values not used in constrained positions and not x.
	// Number of remaining values = (x-1 - lessCount) + (n-x - greaterCount) = n - 1 - lessCount - greaterCount
	// So the number of ways to arrange them is (n - 1 - lessCount - greaterCount)!

	remaining := n - 1 - lessCount - greaterCount
	waysRemaining := fact[remaining]

	result := waysLess * waysGreater % MOD
	result = result * waysRemaining % MOD

	fmt.Println(result)
}

func modPow(base, exp, mod int64) int64 {
	result := int64(1)
	base = base % mod
	for exp > 0 {
		if exp%2 == 1 {
			result = result * base % mod
		}
		exp = exp / 2
		base = base * base % mod
	}
	return result
}
